public class Main {
    static int[] parent, size;

    static int find(int x) {
        int root = x;
        while (parent[root] != root) root = parent[root];
        while (parent[x] != x) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    static void union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    static class MinHeap {
        long[] distances = new long[16];
        int[] nodes = new int[16];
        int size = 0;

        void add(long distance, int node) {
            if (size == distances.length) {
                distances = Arrays.copyOf(distances, size * 2);
                nodes = Arrays.copyOf(nodes, size * 2);
            }
            int i = size++;
            while (i > 0) {
                int p = (i - 1) >>> 1;
                if (distances[p] <= distance) break;
                distances[i] = distances[p];
                nodes[i] = nodes[p];
                i = p;
            }
            distances[i] = distance;
            nodes[i] = node;
        }

        long minDistance() {
            return distances[0];
        }

        int minNode() {
            return nodes[0];
        }

